using ContentOS.Application;
using ContentOS.Contracts;
using ContentOS.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace ContentOS.Infrastructure;

public sealed partial class WatchFactory(CoreDbContext db, IEditorialWorkbench editorial, IUniverseRegistry registry, IMediaLibrary media, IAssetStore store, IWatchMasterStore masters, ISubtitleProvider subtitles, IEnumerable<IVideoRenderer> renderers) : IWatchFactory
{
    private static string Json<T>(T x) => EditorialBinding.Json(x); private static T Read<T>(string x) => EditorialBinding.Read<T>(x); private static Guid Derived(Guid id, string key) => new(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(id + "|WATCH|" + key))[..16]);
    private IVideoRenderer Renderer(string key) => renderers.SingleOrDefault(x => x.Key == key) ?? throw new EvidenceBlockedException("DeployedWATCHRendererRequired");
    private async Task Access(CoreScope s, Guid u, string purpose, CancellationToken ct)
    { if (!await db.Universes.AnyAsync(x => x.Id == u && x.TenantId == s.TenantId, ct)) throw new CoreAccessException(); var role = await db.Members.Where(x => x.TenantId == s.TenantId && x.Actor == s.Actor).Select(x => x.Permission).SingleOrDefaultAsync(ct); if (role == null || purpose == "Admin" && role != "Administrator" || purpose == "Review" && role is not ("Administrator" or "Editor") || purpose == "Write" && role is not ("Administrator" or "Author" or "Editor")) throw new CoreAccessException(); }
    private async Task<T> Command<T>(CoreScope s, Guid u, Guid op, string kind, object request, string purpose, Func<Task<T>> action, CancellationToken ct)
    { if (op == Guid.Empty) throw new RuntimeValidationException("Stable WATCH operation required."); db.ChangeTracker.Clear(); await using var tx = await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable, ct); await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource={"ContentOS.Watch:" + s.TenantId},@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000; IF @r<0 THROW 51000,'WATCH lock unavailable',1;", ct); await Access(s, u, purpose, ct); var hash = EditorialBinding.Hash(new { u, request }); var old = await db.WatchOperations.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == op, ct); if (old != null) { if (old.Actor != s.Actor || old.Kind != kind || old.Fingerprint != hash) throw new RuntimeConflictException("WATCH replay differs."); return Read<T>(old.ResultJson); } var result = await action(); db.WatchOperations.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, OperationId = op, Actor = s.Actor, Kind = kind, Fingerprint = hash, RequestJson = Json(request), ResultJson = Json(result) }); db.SourceAudits.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, Actor = s.Actor, SubjectId = u, Action = "watch." + kind }); try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { throw new CoreConcurrencyException(); } await tx.CommitAsync(ct); return result; }
    private static void Expected(CoreRecord row, string version) { try { if (!row.RowVersion.SequenceEqual(Convert.FromBase64String(version))) throw new CoreConcurrencyException(); } catch (FormatException) { throw new RuntimeValidationException("Valid WATCH rowversion required."); } }
    private Task<WatchProduction> Production(CoreScope s, Guid u, Guid id, CancellationToken ct) => db.WatchProductions.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct).ContinueWith(t => t.GetAwaiter().GetResult() ?? throw new CoreAccessException(), ct, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
    private WatchTemplateView TemplateView(WatchTemplate r) => new(r.Id, Read<RegisterWatchTemplate>(r.SnapshotJson), r.ReviewStatus, Convert.ToBase64String(r.RowVersion));
    private WatchProfileView ProfileView(WatchProfile r) { var c = Read<RegisterWatchProfile>(r.SnapshotJson); return new(r.Id, c, Renderer(c.Renderer).Capabilities, r.Enabled, Convert.ToBase64String(r.RowVersion)); }
    public Task<Guid> TemplateAsync(CoreScope s, Guid u, RegisterWatchTemplate r, CancellationToken ct) => Command(s, u, r.OperationId, "template", r, "Admin", async () => { CoreRules.Text(r.Key, 100, "Template key"); WatchRules.Template(r.Rules); var version = await db.WatchTemplates.Where(x => x.TenantId == s.TenantId && x.UniverseId == u && x.Key == r.Key).Select(x => (int?)x.Version).MaxAsync(ct) ?? 0; if (r.Version != version + 1) throw new RuntimeConflictException("Append template version."); var row = new WatchTemplate { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, Key = r.Key, Version = r.Version, SnapshotJson = Json(r) }; db.WatchTemplates.Add(row); return row.Id; }, ct);
    public async Task<WatchTemplateView[]> TemplatesAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); return (await db.WatchTemplates.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).Take(100).ToListAsync(ct)).Select(TemplateView).ToArray(); }
    public async Task ReviewTemplateAsync(CoreScope s, Guid u, Guid id, WatchReview r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "template-review", new { id, r }, "Review", async () => { var row = await db.WatchTemplates.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct) ?? throw new CoreAccessException(); Expected(row, r.ExpectedRowVersion); MediaRules.Attest(r.Mode, r.EvidenceReference); if (r.Decision is not ("Approve" or "Reject" or "Withdraw") || r.Decision == "Approve" && (row.ReviewStatus != "Draft" || r.Deviations.Length != 0)) throw new EvidenceBlockedException("FreshWATCHLayoutQualityReviewRequired"); row.ReviewStatus = r.Decision == "Approve" ? "Approved" : r.Decision == "Reject" ? "Rejected" : "Withdrawn"; row.ReviewJson = Json(r); return id; }, ct);
    public Task<Guid> ProfileAsync(CoreScope s, Guid u, RegisterWatchProfile r, CancellationToken ct) => Command(s, u, r.OperationId, "profile", r, "Admin", async () => { MediaRules.Attest(r.Mode, r.EvidenceReference); CoreRules.Text(r.Key, 100, "Renderer profile"); if (!System.Text.RegularExpressions.Regex.IsMatch(r.AccountReference, "^local:[A-Za-z0-9_-]{1,100}$") || r.CallCeiling != 0 || r.Currency is not ("INR" or "USD")) throw new EvidenceBlockedException("ShippedWATCHRenderersUseExplicitZeroBudgetLocalBindingsOnly"); var renderer = Renderer(r.Renderer); if (!renderer.Capabilities.Configured) throw new EvidenceBlockedException("ApprovedRendererConfigurationRequired"); if (!await db.WatchTemplates.AnyAsync(x => x.Id == r.TemplateId && x.TenantId == s.TenantId && x.UniverseId == u && x.ReviewStatus == "Approved", ct)) throw new EvidenceBlockedException("ReviewedScopedTemplateRequired"); var version = await db.WatchProfiles.Where(x => x.TenantId == s.TenantId && x.UniverseId == u && x.Key == r.Key).Select(x => (int?)x.Version).MaxAsync(ct) ?? 0; if (r.Version != version + 1) throw new RuntimeConflictException("Append renderer profile version."); var row = new WatchProfile { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, Key = r.Key, Version = r.Version, SnapshotJson = Json(r) }; db.WatchProfiles.Add(row); return row.Id; }, ct);
    public async Task<WatchProfileView[]> ProfilesAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); return (await db.WatchProfiles.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).Take(100).ToListAsync(ct)).Select(ProfileView).ToArray(); }
    public async Task DisableProfileAsync(CoreScope s, Guid u, Guid id, WatchControl r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "profile-disable", new { id, r }, "Admin", async () => { var row = await db.WatchProfiles.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct) ?? throw new CoreAccessException(); Expected(row, r.ExpectedRowVersion); CoreRules.Text(r.EvidenceReference, 1000, "Disable evidence"); row.Enabled = false; return id; }, ct);
    private async Task Source(CoreScope s, WatchSnapshot snap, string purpose, CancellationToken ct)
    {
        var item = await db.EditorialItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == snap.Script.Id && x.TenantId == s.TenantId, ct) ?? throw new CoreAccessException(); var revision = await EditorialBinding.Revision(db, item, ct); if (revision.Id != snap.Script.RevisionId || item.State is not ("Approved" or "Scheduled" or "Published") || !item.ApprovalId.HasValue || !snap.Script.Approvals.Any(x => x.Id == item.ApprovalId && x.Current && x.Fingerprint == snap.Script.Fingerprint)) throw new EvidenceBlockedException("PinnedCurrentScriptApprovalRequired");
        await EditorialBinding.AssertExport(db, s, revision.Id, purpose == "Publish" ? "Publish" : "Export", ct); if (purpose is "Generate" or "Publish") await new SourceRightsGuard(db).CheckAsync(s, revision.Id, new(purpose, await db.Contents.Where(x => x.Id == item.ContentId).Select(x => x.LocaleId).SingleAsync(ct), "IN", "Video", Adaptation: true), ct);

    }
    public async Task<WatchProductionView> CreateAsync(CoreScope s, Guid u, CreateWatch r, CancellationToken ct)
    {
        await Access(s, u, "Admin", ct); var packet = await editorial.InspectAsync(s, u, r.EditorialItemId, ct); if (packet.Current == null || packet.SourceOutputWithheld || packet.State is not ("Approved" or "Scheduled" or "Published") || !packet.Approvals.Any(x => x.Current)) throw new EvidenceBlockedException("ApproveCurrentScriptBeforeWATCH"); WatchRules.Script(r, packet.Current.Body);
        var profileRow = await db.WatchProfiles.AsNoTracking().SingleOrDefaultAsync(x => x.Id == r.ProfileId && x.TenantId == s.TenantId && x.UniverseId == u && x.Enabled, ct) ?? throw new CoreAccessException(); var profile = ProfileView(profileRow); var templateRow = await db.WatchTemplates.AsNoTracking().SingleOrDefaultAsync(x => x.Id == profile.Configuration.TemplateId && x.TenantId == s.TenantId && x.UniverseId == u && x.ReviewStatus == "Approved", ct) ?? throw new EvidenceBlockedException("ReviewedScopedTemplateRequired"); var template = TemplateView(templateRow);
        decimal reserved = 0; foreach (var generation in r.Scenes.SelectMany(x => new[] { x.ImageGeneration, x.VoiceGeneration }).Where(x => x != null).Select(x => x!)) { var mediaProfile = await db.MediaProfiles.AsNoTracking().SingleOrDefaultAsync(x => x.Id == generation.ProfileId && x.TenantId == s.TenantId && x.UniverseId == u && x.Enabled, ct) ?? throw new CoreAccessException(); var config = Read<RegisterMediaProfile>(mediaProfile.SnapshotJson); if (config.Currency != profile.Configuration.Currency) throw new EvidenceBlockedException("WATCHMediaCurrencyMustMatchEpisodeBudget"); reserved += config.CallCeiling; }
        if (reserved > r.MaxMediaCost) throw new EvidenceBlockedException("WATCHMediaReservationExceedsEpisodeBudget");
        var head = await db.Contents.AsNoTracking().SingleAsync(x => x.Id == packet.ContentId, ct); if (!profile.Capabilities.Locales.Contains(head.LocaleId) || r.Aspects.Any(x => !profile.Capabilities.Aspects.Contains(x))) throw new EvidenceBlockedException("UnsupportedRendererLocaleOrAspect"); var characters = await registry.CharactersAsync(s, u, ct); var presentations = await registry.PresentationsAsync(s, u, ct); var cast = new List<WatchCast>();
        foreach (var group in r.Scenes.GroupBy(x => new { x.CharacterId, x.PresentationId }))
        { var c = characters.SingleOrDefault(x => x.CharacterId == group.Key.CharacterId) ?? throw new CoreAccessException(); var p = presentations.SingleOrDefault(x => x.Id == group.Key.PresentationId) ?? throw new CoreAccessException(); if (c.Status != "Active" || c.Profile.ReviewStatus != "Approved" || p.ReviewStatus != "Approved" || p.Rules.ProfileRevisionId != c.Profile.Id || p.Rules.AudienceId != head.AudienceId || p.Rules.Locale != head.LocaleId) throw new EvidenceBlockedException("ExactReviewedWATCHCastAndPresentationRequired"); await MediaRightsGuard.Presentation(db, s, u, p.Id, "Reuse", ct); var productionCasts = packet.Episodes.SelectMany(x => x.Cast).ToArray(); if (productionCasts.Length == 0 || !productionCasts.Any(x => x.Character.CharacterId == c.CharacterId && x.Character.Profile.Id == c.Profile.Id && x.Presentation?.Id == p.Id)) throw new EvidenceBlockedException("WATCHCastMustMatchApprovedScriptCast"); var package = await db.MediaPackages.AsNoTracking().SingleOrDefaultAsync(x => x.PresentationRevisionId == p.Id && x.ReviewStatus == "Approved", ct) ?? throw new EvidenceBlockedException("ApprovedM16PackageRequired"); var rules = Read<CharacterMediaRules>(package.SnapshotJson); cast.Add(new(c, p, c.Profile.Rules.ContinuityTags, rules.StyleRules, productionCasts.Where(x => x.Character.CharacterId == c.CharacterId).Select(x => x.Role).Distinct().ToArray())); }
        var boundTrends = await db.TrendBindings.AsNoTracking().Where(x => x.ContentRevisionId == packet.RevisionId).Select(x => x.BriefId).Distinct().ToArrayAsync(ct); if (boundTrends.Length > 0 && (r.TrendBriefId == null || boundTrends.Any(x => x != r.TrendBriefId))) throw new EvidenceBlockedException("PinEveryBoundTrendBriefBeforeWATCH"); TrendStorySnapshot? trend = null; if (r.TrendBriefId.HasValue) { var brief = await db.TrendStoryBriefs.AsNoTracking().SingleOrDefaultAsync(x => x.Id == r.TrendBriefId && x.TenantId == s.TenantId && x.UniverseId == u && x.State == "Approved", ct) ?? throw new EvidenceBlockedException("ApprovedCurrentTrendBriefRequired"); trend = Read<TrendStorySnapshot>(brief.SnapshotJson); if (!await db.TrendBindings.AnyAsync(x => x.BriefId == brief.Id && x.ContentRevisionId == packet.RevisionId, ct)) throw new EvidenceBlockedException("ExactTrendScriptBindingRequired"); }
        var snapshot = new WatchSnapshot(r, packet, profile, template, cast.ToArray(), trend); foreach (var scene in r.Scenes) { if (scene.VoiceGeneration != null) { var package = await db.MediaPackages.AsNoTracking().SingleAsync(x => x.PresentationRevisionId == scene.PresentationId && x.TenantId == s.TenantId && x.UniverseId == u, ct); await VoiceProfile(s, u, Read<CharacterMediaRules>(package.SnapshotJson), scene.VoiceGeneration.ProfileId, ct); } else if (scene.VoiceVersionId.HasValue) { var voice = await MediaRightsGuard.Assert(db, s, u, scene.VoiceVersionId.Value, "Reuse", true, ct); await SceneIdentity(s, u, snapshot, scene, voice, true, ct); } }
        var id = await Command(s, u, r.OperationId, "create", r, "Admin", async () =>
        {
            await Source(s, snapshot, "Generate", ct); if (!await db.WatchProfiles.AnyAsync(x => x.Id == r.ProfileId && x.Enabled, ct) || !await db.WatchTemplates.AnyAsync(x => x.Id == template.Id && x.ReviewStatus == "Approved", ct)) throw new EvidenceBlockedException("RendererOrTemplateWithdrawn");
            var version = await db.WatchProductions.Where(x => x.TenantId == s.TenantId && x.UniverseId == u && x.Key == r.Key).Select(x => (int?)x.Version).MaxAsync(ct) ?? 0; if (r.Version != version + 1) throw new RuntimeConflictException("Append WATCH version; old episode/master remains immutable."); if (r.ParentProductionId.HasValue) { await Production(s, u, r.ParentProductionId.Value, ct); CoreRules.Text(r.CorrectionNote, 1000, "Correction reason"); }
            var content = new ContentItem { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, SubjectId = head.SubjectId, AudienceId = head.AudienceId, LocaleId = head.LocaleId, CurrentVersion = 1 }; var rev = new ContentRevision { Id = Guid.NewGuid(), ContentId = content.Id, Version = 1, OperationId = Derived(r.OperationId, "core"), Title = packet.Current.Title, Body = packet.Current.Body, Kind = packet.Current.Kind, RightsStatus = packet.Current.RightsStatus, Provenance = "WATCH derived from exact approved script " + packet.RevisionId }; db.Contents.Add(content); db.Revisions.Add(rev); await db.SaveChangesAsync(ct); db.Provenance.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, ContentRevisionId = rev.Id, ParentRevisionId = packet.RevisionId, Relation = "Adaptation" });
            var row = new WatchProduction { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, Key = r.Key, Version = r.Version, Actor = s.Actor, ProfileId = r.ProfileId, CoreRevisionId = rev.Id, SnapshotJson = Json(snapshot), DeadlineUtc = DateTimeOffset.UtcNow.AddSeconds(r.DeadlineSeconds) }; db.WatchProductions.Add(row); var steps = new[] { "Storyboard", "Assets", "Voice", "Timing" }.Concat(r.Aspects.Select(x => "Render" + x)).Concat(["QA", "Approval"]).ToArray(); for (var i = 0; i < steps.Length; i++) db.WatchStages.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, ProductionId = row.Id, Kind = steps[i], Sequence = i }); return row.Id;
        }, ct); return await InspectAsync(s, u, id, ct);
    }
    public async Task<WatchProductionView[]> ListAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); var ids = await db.WatchProductions.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).OrderByDescending(x => x.CreatedUtc).Take(50).Select(x => x.Id).ToArrayAsync(ct); var rows = new List<WatchProductionView>(); foreach (var id in ids) rows.Add(await InspectAsync(s, u, id, ct)); return rows.ToArray(); }
    public async Task<WatchProductionView> InspectAsync(CoreScope s, Guid u, Guid id, CancellationToken ct)
    { await Access(s, u, "Read", ct); var row = await Production(s, u, id, ct); var snap = Read<WatchSnapshot>(row.SnapshotJson); var blocks = new List<string>(); try { await Source(s, snap, "Read", ct); if (row.TimelineJson != null) foreach (var scene in Read<WatchTimeline>(row.TimelineJson).Scenes) { await MediaRightsGuard.WatchVoice(db, s, u, scene, ct); await MediaRightsGuard.Assert(db, s, u, scene.Image.Id, "Reuse", true, ct); await MediaRightsGuard.Assert(db, s, u, scene.Voice.Id, "Reuse", true, ct); if (scene.Music != null) await MediaRightsGuard.Assert(db, s, u, scene.Music.Id, "Reuse", true, ct); } } catch (Exception e) when (e is EvidenceBlockedException or RightsBlockedException) { blocks.Add(e.Message); } if (blocks.Count > 0) { snap = snap with { Script = snap.Script with { Current = null, Previous = null, FactoryHistory = [], Variants = [], Episodes = [], ProductionRuns = [], Evaluations = [], Claims = [], Citations = [], Disagreements = [], SourceOutputWithheld = true }, Cast = [], Trend = null, Request = snap.Request with { Scenes = snap.Request.Scenes.Select(x => x with { ImageGeneration = null, VoiceGeneration = null }).ToArray() } }; } var stages = await db.WatchStages.AsNoTracking().Where(x => x.ProductionId == id).OrderBy(x => x.Sequence).ToArrayAsync(ct); var artifacts = (await db.WatchArtifacts.AsNoTracking().Where(x => x.ProductionId == id).ToArrayAsync(ct)).Select(x => Read<WatchArtifactView>(x.SnapshotJson)).ToArray(); if (row.State is "Cancelled" or "Withdrawn") blocks.Add("EpisodeCancelledOrWithdrawn"); if (row.State != "Approved") blocks.Add("FinalEpisodeReviewRequired"); return new(row.Id, row.Key, row.Version, row.State, row.CoreRevisionId, snap, row.TimelineJson == null || snap.Script.SourceOutputWithheld ? null : Read<WatchTimeline>(row.TimelineJson), stages.Select(x => new WatchStageView(x.Id, x.Kind, x.Sequence, x.State, x.Attempts, x.Outcome, x.ActualCost, Convert.ToBase64String(x.RowVersion))).ToArray(), artifacts, stages.Sum(x => x.ActualCost), snap.Profile.Configuration.Currency, row.ReviewMinutes, Convert.ToBase64String(row.RowVersion), blocks.ToArray()); }
}
public static class WatchServices
{ public static IServiceCollection AddWatchFactory(this IServiceCollection s) { s.AddScoped<IWatchFactory, WatchFactory>(); s.AddScoped<IWatchMasterStore, WatchMasterStore>(); return s; } }




